description:
Write `final class Template` with `static String render(String template, Map<String, Object> values)`:

- `${name}` is replaced by `String.valueOf(values.get(name))`;
- `${name:FORMAT}` formats the value with `String.format(Locale.ROOT, FORMAT, value)`, for example `${price:%.2f}`;
- names are letters, digits, `_` and `.`; a name that is not in the map leaves the placeholder exactly as it was;
- `$${` produces a literal `${` (an escape), and a `$` or `\` inside a value never causes trouble.

```java
Template.render("Hello ${name}, you owe ${amount:%.2f}.", Map.of("name", "Ada", "amount", 12.5))
// "Hello Ada, you owe 12.50."
```

starter.Template.java:
import java.util.*;

public final class Template {
    public static String render(String template, Map<String, Object> values) {
        String out = template;
        for (var e : values.entrySet()) out = out.replaceAll("\\$\\{" + e.getKey() + "}", e.getValue().toString());
        return out;
    }
}

solution.Template.java:
import java.util.*;
import java.util.regex.*;

public final class Template {
    private static final Pattern PLACEHOLDER = Pattern.compile("\\$(\\$)?\\{([\\w.]+)(?::([^}]*))?}");

    public static String render(String template, Map<String, Object> values) {
        return PLACEHOLDER.matcher(template).replaceAll(r -> {
            String whole = r.group();
            if (r.group(1) != null) return Matcher.quoteReplacement(whole.substring(1));
            String name = r.group(2);
            if (!values.containsKey(name)) return Matcher.quoteReplacement(whole);
            Object value = values.get(name);
            String text = r.group(3) == null ? String.valueOf(value) : String.format(Locale.ROOT, r.group(3), value);
            return Matcher.quoteReplacement(text);
        });
    }
}

unitTests:
test("plain and formatted values", () -> {
    checkEq(Template.render("Hello ${name}, you owe ${amount:%.2f}.", Map.of("name", "Ada", "amount", 12.5)),
            "Hello Ada, you owe 12.50.");
    checkEq(Template.render("${n:%05d}|${n:%x}", Map.of("n", 255)), "00255|ff");
});

test("unknown names stay", () -> {
    checkEq(Template.render("Hi ${who}", Map.of()), "Hi ${who}");
});

test("dollars and backslashes in values are safe", () -> {
    checkEq(Template.render("cost: ${c}", Map.of("c", "$5 \\ each")), "cost: $5 \\ each");
});

test("an escaped placeholder", () -> {
    checkEq(Template.render("write $${name} to insert a name", Map.of("name", "Ada")), "write ${name} to insert a name");
});

test("dotted names", () -> {
    checkEq(Template.render("${user.city}", Map.of("user.city", "London")), "London");
});

